pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 deposit1, uint256 deposit2, uint256 collectAmt) public {
        vm.assume(caller != address(0));
        deposit1 = bound(deposit1, 1, 100 ether);
        deposit2 = bound(deposit2, 1, 100 ether);
        collectAmt = bound(collectAmt, 1, 100 ether);

        // Ensure we have enough balance for deposits
        uint256 totalDeposits = deposit1 + deposit2;
        vm.deal(address(this), totalDeposits);

        vm.startPrank(caller, caller);
        // Deposit twice
        (bool success1,) = address(c).call{value: deposit1}(abi.encodeWithSignature("Put(uint256)", 0));
        (bool success2,) = address(c).call{value: deposit2}(abi.encodeWithSignature("Put(uint256)", 0));
        // Try to collect
        (bool success3,) = address(c).call(abi.encodeWithSignature("Collect(uint256)", collectAmt));
        vm.stopPrank();

        // The rule: after any operations ending with Collect, caller's Acc.balance <= total deposits (0 if mutant)
        // In reference: balance = deposited amount (deposit1+deposit2) minus collected amount (if success3)
        uint256 finalBalance = c.Acc(caller).balance;
        if (success3) {
            // collect succeeded, balance should be totalDeposits - collectAmt (or 0 if underflow)
            assertTrue(finalBalance == (totalDeposits >= collectAmt ? totalDeposits - collectAmt : 0), "Rule broken");
        } else {
            // collect reverted, balance should be totalDeposits
            assertTrue(finalBalance == totalDeposits, "Rule broken");
        }
    }
}

