pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 amount, uint256 unlockTime) public {
        vm.assume(amount > 0 && amount < 100 ether);
        // First, fund the contract with some ETH so the reference won't revert on sub_uint256
        vm.deal(address(c), 10 ether);
        // Set unlockTime to be in the past so Collect can succeed
        if (unlockTime > block.timestamp) unlockTime = unlockTime % (block.timestamp + 1);
        // Call Put to add msg.sender's balance (but we don't send ETH, so balance stays 0)
        // Actually we will call Collect directly with a prank to simulate a sender
        address user = address(0x1234);
        vm.deal(user, amount);
        vm.prank(user);
        // Record balance before
        uint256 balanceBefore = address(c).balance;
        // Call Collect(amount) - will revert if sub_uint256 fails (M) or succeed (P)
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, amount));
        uint256 balanceAfter = address(c).balance;
        // The rule: if Collect succeeded, balance must not change (since it only modifies internal mapping)
        // If it reverted, balance also unchanged.
        assertTrue(balanceBefore == balanceAfter);
    }
}

