pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 amount) public {
        // Bounds to avoid overflow and ensure sufficient balance
        vm.assume(amount <= address(this).balance);
        vm.assume(amount >= 0);

        // Initially fund the contract a known amount
        vm.deal(address(c), 1 ether);
        // Set a test account with a balance
        address user = address(0x123);
        vm.deal(user, 10 ether);

        // User puts some ether into the contract via Put (simplified: call Put with unlockTime now)
        vm.prank(user);
        c.Put{value: amount}(block.timestamp);

        // Now call Collect to withdraw
        uint collectAmount = amount;
        vm.prank(user);
        (bool successCollect,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // Check the invariant: total ether in contract equals sum of Acc balances
        // We can compute sum of Acc balances by iterating? But we only have public mapping, no iterator.
        // Instead we use a simpler invariant: After Collect, the contract's ether balance is unchanged relative to before Collect if the call reverts?
        // Actually we need a general rule that the reference satisfies and bug breaks.
        // Bug: reentrancy protection disabled allows draining. But we cannot easily sum all Acc balances.
        // Alternative: Use the fact that after a _successful_ Collect, the contract balance decreases by exactly collectAmount.
        // So rule: If Collect reverts, contract balance stays same; if Collect succeeds, contract balance decreases by collectAmount.
        // The bug causes extra ether leaks (maybe more balance decrease than collectAmount). But we need a deterministic property.
        // Simpler: After call, the contract's balance is <= address(c).balance before call.
        uint256 balanceAfter = address(c).balance;
        uint256 expectedBalance = 1 ether + (amount - (successCollect ? collectAmount : 0));
        assertTrue(balanceAfter == expectedBalance, "Balance invariant violated");
    }
}

