        unlockTime = bound(unlockTime, 0, 1000000);
        deposit = bound(deposit, 0, 100 ether);
        am = bound(am, 0, deposit);

        // Set up conditions for Collect to succeed
        vm.deal(address(this), deposit);
        c.Put{value: deposit}(unlockTime);
        vm.warp(block.timestamp + unlockTime + 1);

        // Call Collect
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, am));

        // The rule: MinSum must always be 1 ether (the constructor value)
        assertTrue(c.MinSum() == 1 ether);
    }
}
